        const baseHeight = finalPoints.length > 0 ? finalPoints[0].y : 0;

        // ... (Rect, Circle, Arc logic)
        if (tool === ToolType.DRAW_RECT && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const width = Math.abs(end.x - start.x);
             const depth = Math.abs(end.z - start.z);
             if (width >= 0.01 && depth >= 0.01) {
                 const cx = (start.x + end.x) / 2;
                 const cz = (start.z + end.z) / 2;
                 const halfW = width / 2;
                 const halfD = depth / 2;
                 const points: IPoint[] = [{ x: -halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: -halfD }, { x: halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: halfD }, { x: -halfW, y: 0, z: -halfD }];
                 addShape({ id: `rect-${Date.now()}`, type: 'flat', name: '地板', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [cx, 0, cz], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_CIRCLE && finalPoints.length >= 2) {
            const start = finalPoints[0];
            const end = finalPoints[1];
            const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
            if (radius > 0.01) {
                const points = createCirclePoints(radius);
                addShape({ id: `circle-${Date.now()}`, type: 'flat', name: '圓形', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, 0, start.z], rotation: 0, scale: [1, 1, 1] });
                shapeCreated = true;
            }
        } else if (tool === ToolType.DRAW_ARC && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[1];
             const radius = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);
             if (radius > 0.01) {
                 const points = createCirclePoints(radius); 
                 addShape({ id: `arc-${Date.now()}`, type: 'flat', name: '弧形', points, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [start.x, 0, start.z], rotation: 0, scale: [1, 1, 1] });
                 shapeCreated = true;
             }
        } else if (tool === ToolType.DRAW_LINE && finalPoints.length >= 2) {
             const start = finalPoints[0];
             const end = finalPoints[finalPoints.length - 1]; 
             const dist = Math.sqrt((end.x - start.x)**2 + (end.z - start.z)**2);

             if (dist >= 0.01) {
                const idsToRemove = new Set<string>();
                const shapesToAddList: IShape[] = [];

                // 1. Edge Fragmentation (Planar Graph for Lines)
                const existingEdges: {start: IPoint, end: IPoint, originalId: string}[] = [];
                shapes.forEach(shape => {
                    if (shape.name === 'Edge') {
                        const eps = getLineEndpoints(shape);
                        if (eps) {
                            existingEdges.push({ start: {x: eps[0].x, y: 0, z: eps[0].z}, end: {x: eps[1].x, y: 0, z: eps[1].z}, originalId: shape.id });
                            idsToRemove.add(shape.id); 
                        }
                    }
                });

                const allSegments = existingEdges.map(e => ({ start: e.start, end: e.end }));
                allSegments.push({ start: {x: start.x, y: 0, z: start.z}, end: {x: end.x, y: 0, z: end.z} });

                const fragmented = fragmentSegments(allSegments);
                const cycles = findClosedCycles(fragmented);

                fragmented.forEach(seg => {
                     const dx = seg.end.x - seg.start.x;
                     const dz = seg.end.z - seg.start.z;
                     const len = Math.sqrt(dx*dx + dz*dz);
                     const angle = Math.atan2(dz, dx);
                     const cx = (seg.start.x + seg.end.x) / 2;
                     const cz = (seg.start.z + seg.end.z) / 2;
                     const thickness = 0.02; 
                     const halfL = len / 2;
                     const halfW = thickness / 2;
                     const points = [ { x: -halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: -halfW }, { x: halfL, y: 0, z: halfW }, { x: -halfL, y: 0, z: halfW } ];
                     shapesToAddList.push({ id: `edge-${Date.now()}-${Math.random()}`, type: 'flat', name: 'Edge', points, height: 0.005, color: '#334155', position: [cx, baseHeight, cz], rotation: -angle, scale: [1, 1, 1] });
                });

                cycles.forEach(cycle => {
                    const center = getBoundingCenter(cycle);
                    const centeredPoints = cycle.map(p => ({ x: p.x - center.x, y: 0, z: p.z - center.z }));
                    shapesToAddList.push({ id: `floor-${Date.now()}-${Math.random()}`, type: 'flat', name: '平面', points: centeredPoints, height: DEFAULT_HEIGHT, color: FLAT_COLOR, position: [center.x, baseHeight, center.z], rotation: 0, scale: [1, 1, 1] });
                });

                // 2. Face Splitting Logic (Cutting Polygons)
                shapes.forEach(shape => {
                    if ((shape.type === 'flat' || shape.type === 'solid') && shape.name !== 'Edge' && shape.points.length > 2) {

                        // Transform points to world space for intersection calculation
                        const worldPoints = shape.points.map(p => {
                            const vec = transformPoint(p, shape);
                            return { x: vec.x, y: vec.y, z: vec.z };
                        });

                        const splitResult = splitPolygonByLine(worldPoints, start, end);

                        if (splitResult) {
                            const [poly1Points, poly2Points] = splitResult;
                            idsToRemove.add(shape.id);

                            [poly1Points, poly2Points].forEach(newPoints => {
                                // Calculate new center for the split piece
                                const center = getBoundingCenter(newPoints);

                                // Relativize points to the new center. 
                                // Since we calculated intersections in world space, we must reset rotation to 0 for simplicity.
                                const localPoints = newPoints.map(p => ({
                                    x: p.x - center.x,
                                    y: 0,
                                    z: p.z - center.z
                                }));

                                shapesToAddList.push({
                                    ...shape,
                                    id: `split-${Date.now()}-${Math.random()}`,
                                    points: localPoints,
                                    position: [center.x, shape.position[1], center.z],
                                    rotation: 0, // Reset rotation as points are now baked in world orientation relative to new center
                                    scale: [1, 1, 1] // Reset scale
                                });
                            });
                        }
                    }
                });

                if (idsToRemove.size > 0 || shapesToAddList.length > 0) {
                     replaceShapes(Array.from(idsToRemove), shapesToAddList);
                }
                shapeCreated = true;
             }
        }

        if (shapeCreated) {
            setDrawPoints([]);
            setTool(ToolType.SELECT); 
            setMeasurement('');
            setTypedInput('');
        }
    }, [tool, addShape, wallThickness, setTool, replaceShapes, updateShape, shapes, setMeasurement]);

    // Handle Manual Input Submit (Enter key)
    const handleInputSubmit = useCallback(() => {
        if (!typedInput || drawPoints.length === 0) return;

        const start = drawPoints[drawPoints.length - 1];
        const startVec = new THREE.Vector3(start.x, start.y, start.z);
        const cursorVec = cursorPos.clone();

        let targetVec = new THREE.Vector3();
        const direction = cursorVec.clone().sub(startVec).normalize();

        // Handling for different tools
        if (tool === ToolType.DRAW_RECT) {
             const parts = typedInput.split(/[, ]+/).filter(p => p.trim() !== '').map(parseFloat);
             if (parts.length > 0 && !parts.some(isNaN)) {
                 const w = parts[0];
                 const d = parts.length > 1 ? parts[1] : w;

                 const dx = cursorVec.x - startVec.x;
                 const dz = cursorVec.z - startVec.z;
                 const signX = dx >= 0 ? 1 : -1;
                 const signZ = dz >= 0 ? 1 : -1;

                 targetVec.set(startVec.x + signX * w, startVec.y, startVec.z + signZ * d);
             } else {
                 return;
             }
        } else {
             // Line, Circle, Arc, Measure: Single value length/radius
             const val = parseFloat(typedInput);
             if (isNaN(val)) return;

             // If cursor is at start (no direction), use default X? No, wait for cursor move.
             // If direction length is 0, default to X axis
             if (cursorVec.distanceTo(startVec) < 0.001) {
                 direction.set(1, 0, 0);
             }

             targetVec = startVec.clone().add(direction.multiplyScalar(val));
        }

        const finalPoints = [...drawPoints, { x: targetVec.x, y: targetVec.y, z: targetVec.z }];
        finishShape(finalPoints);

    }, [typedInput, drawPoints, cursorPos, tool, finishShape]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        if (e.button !== 0) return;
        e.stopPropagation();
        setIsDragging(true);
        setTypedInput(''); // Clear input on click

        // CRITICAL FIX: Sync cursor pos to ensure preview starts at click point
        // This prevents the "Drawing Preview" from using a default (0,0,0) coordinate momentarily.
        setCursorPos(e.point.clone());

        const pt = e.point.clone();

        if (drawPoints.length === 0) {
            setDrawPoints([{ x: pt.x, y: pt.y, z: pt.z }]);
            if (tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC) {
                 setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        } else {
            if (tool === ToolType.DRAW_LINE) {
                setDrawPoints(prev => [...prev, { x: pt.x, y: pt.y, z: pt.z }]);
            }
        }
    }, [tool, drawPoints]);

    const handlePointerUp = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
        setIsDragging(false);

        if ((tool === ToolType.DRAW_RECT || tool === ToolType.DRAW_CIRCLE || tool === ToolType.DRAW_ARC || tool === ToolType.DRAW_LINE) && drawPoints.length >= 2) {
             const current = { x: cursorPos.x, y: cursorPos.y, z: cursorPos.z };
             const points = [...drawPoints];
             points[points.length-1] = current;
             finishShape(points);
        }
    }, [tool, drawPoints, cursorPos, finishShape]);

    const handleClick = useCallback((e: ThreeEvent<MouseEvent>) => {
    }, []);

    // Global Key Listener for Input
    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
             // If not drawing, ignore numbers (unless we want to support typing dimension for selected object later)
             if ([ToolType.SELECT, ToolType.PUSH_PULL].includes(tool)) return;
             if (drawPoints.length === 0) return; // Need at least a start point

             if (e.key === 'Enter') {
                 handleInputSubmit();
                 return;
             }
             if (e.key === 'Backspace') {
                 setTypedInput(prev => prev.slice(0, -1));
                 return;
             }

             // Allow numbers, dot, comma, minus
             if (/^[0-9.,-]$/.test(e.key)) {
                 setTypedInput(prev => prev + e.key);
             }
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, drawPoints, handleInputSubmit]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, drawingHeight, handlePointerDown, handlePointerUp, handleClick, typedInput };
};

const EditorScene: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
    const { shapes, selectedIds, selectShape, tool } = useApp();
    const { ppState, handlePointerMove, handlePointerDown: ppDown, handlePointerUp: ppUp, tempShape, isDragging: isPPDragging } = usePushPullManager();
    const { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging: isDrawing, drawingHeight, handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick, typedInput } = useDrawingManager();
    const [isObjectDragging, setIsObjectDragging] = useState(false);

    const renderShapes = useMemo(() => {
        if (tempShape && ppState.hoveredShapeId) {
            return shapes.map(s => s.id === ppState.hoveredShapeId ? tempShape : s);
        }
        return shapes;
    }, [shapes, tempShape, ppState.hoveredShapeId]);

    const raycaster = useThree((state) => state.raycaster);
    useEffect(() => {
        raycaster.params.Line.threshold = 0.2;
    }, [raycaster]);

    const pushPullHandlers = useMemo(() => ({ handlePointerDown: ppDown, handlePointerUp: ppUp, handlePointerMove: handlePointerMove }), [ppDown, ppUp, handlePointerMove]);
    const drawingHandlers = useMemo(() => ({ handlePointerDown: drawDown, handlePointerUp: drawUp, handleClick: handleClick }), [drawDown, drawUp, handleClick]);

    return (
        <>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 20, 5]} intensity={1} castShadow shadow-mapSize={[2048, 2048]}>
                <orthographicCamera attach="shadow-camera" left={-20} right={20} top={20} bottom={-20} />
            </directionalLight>

            <Grid position={[0, -0.01, 0]} args={[40, 40]} cellSize={1} cellThickness={1} cellColor="#e2e8f0" sectionSize={5} sectionThickness={1.5} sectionColor="#cbd5e1" fadeDistance={50} infiniteGrid />

            <group 
                onPointerDown={(e) => {
                    if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawDown(e);
                    else selectShape('', false); 
                }} 
                onPointerUp={(e) => {
                         if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) drawUp(e);
                }}
                onPointerMove={(e) => {
                         if (tool === ToolType.PUSH_PULL) handlePointerMove(e);
                }}
            >
                <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
                    <planeGeometry args={[100, 100]} />
                    <meshBasicMaterial visible={false} /> 
                </mesh>
            </group>

            {renderShapes.map(shape => (
                <ShapeRenderer 
                    key={shape.id} 
                    shape={shape} 
                    isSelected={selectedIds.includes(shape.id)} 
                    onSelect={(e) => {
                        selectShape(shape.id, e.shiftKey || (tool === ToolType.SELECT && selectedIds.length > 0 && e.metaKey)); 
                    }}
                    pushPullState={ppState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setIsObjectDragging}
                />
            ))}

            <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setCursorPos} setSnapInfo={setSnapInfo} cursorPos={cursorPos} snapInfo={snapInfo} drawPoints={drawPoints} isDragging={isDrawing} drawingHeight={drawingHeight} typedInput={typedInput} />

            <SelectionGizmo />

            <OrbitControls makeDefault minDistance={2} maxDistance={50} dampingFactor={0.1} enabled={!isDrawing && !isPPDragging && !isObjectDragging} />
            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
            <CameraHandler view={view} onFinished={onViewFinished} />
        </>
    );
};

const Viewport: React.FC = () => {
    const [view, setView] = useState<string|null>(null);

    return (
        <div className="w-full h-full relative bg-white">
             <Canvas 
                shadows 
                camera={{ position: [10, 10, 10], fov: 50 }}
                gl={{ 
                    preserveDrawingBuffer: true,
                    powerPreference: "high-performance"
                }}
             >
                <color attach="background" args={['#ffffff']} />
                <EditorScene view={view} onViewFinished={() => setView(null)} />
            </Canvas>

            <div className="absolute top-4 right-1/2 translate-x-1/2 flex gap-2 bg-slate-800/80 p-1 rounded-lg backdrop-blur-sm border border-slate-700">
                <button onClick={() => setView('top')} className="px-3 py-1 text-xs text-slate-300 hover:text-white hover:bg-slate-700 rounded">上視圖</button>
                <button onClick={() => setView('front')} className="px-3 py-1 text-xs text-slate-300 hover:text-white hover:bg-slate-700 rounded">前視圖</button>
                <button onClick={() => setView('right')} className="px-3 py-1 text-xs text-slate-300 hover:text-white hover:bg-slate-700 rounded">右視圖</button>
            </div>

            <div className="absolute bottom-6 left-6">
                <AIAssistant />
            </div>

            <div className="absolute bottom-6 right-6 text-slate-500 text-[10px] pointer-events-none select-none">
                 v1.0.0
            </div>
        </div>
    );
};

export default Viewport;

import { Vector3 } from 'three';

export enum ToolType {
  SELECT = 'SELECT',
  PUSH_PULL = 'PUSH_PULL', // 推拉工具 (調整長寬高)
  DRAW_LINE = 'DRAW_LINE', // 直線
  DRAW_RECT = 'DRAW_RECT', // 矩形
  DRAW_CIRCLE = 'DRAW_CIRCLE', // 圓形
  DRAW_ARC = 'DRAW_ARC', // 弧形 (門)
}

export type ShapeType = 'solid' | 'flat'; // 立體 | 平面

export type TransformMode = 'translate' | 'scale'; // 移動或縮放

export interface IPoint {
  x: number;
  y: number;
  z: number;
}

export interface ILayer {
  id: string;
  name: string;
  visible: boolean;
  locked: boolean;
}

export interface IShape {
  id: string;
  groupId?: string; // ID for grouping multiple objects
  layerId: string; // ID of the layer this shape belongs to
  type: ShapeType;
  points: IPoint[]; // 地面上的 2D 輪廓點
  height: number;
  color: string;
  position: [number, number, number];
  rotation: number; // Y 軸旋轉 (弧度)
  scale: [number, number, number]; // 新增縮放比例
  name: string;
}

export interface ISceneState {
  shapes: IShape[];
  layers: ILayer[];
  selectedId: string | null;
  tool: ToolType;
  gridSize: number;
}

// AI Generation Types
export interface AIGeneratedItem {
  name: string;
  width: number;
  depth: number;
  height: number;
  color: string;
  x: number;
  z: number;
}

import React, { createContext, useContext, useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { IShape, ToolType, IPoint, TransformMode, ILayer } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

type UnitType = 'm' | 'cm';

interface AppContextType {
  // Project Info
  projectName: string;
  setProjectName: (name: string) => void;

  // Shapes
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void;
  removeShape: (id: string) => void;
  removeSelected: () => void;
  replaceShapes: (idsToRemove: string[], newShapes: IShape[]) => void;
  copySelected: () => void;
  groupSelected: () => void;
  ungroupSelected: () => void;

  // Layers
  layers: ILayer[];
  activeLayerId: string;
  setActiveLayerId: (id: string) => void;
  addLayer: (name: string) => void;
  removeLayer: (id: string) => void;
  toggleLayerVisibility: (id: string) => void;
  updateLayerName: (id: string, name: string) => void;

  // Selection
  selectedIds: string[];
  selectShape: (id: string, multi?: boolean) => void;
  deselectAll: () => void;
  selectedId: string | null; 
  setSelectedId: (id: string | null) => void;

  // Tools & State
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  transformMode: TransformMode;
  setTransformMode: (mode: TransformMode) => void;
  clearScene: () => void;
  addAIShapes: (items: any[]) => void;
  unit: UnitType;
  setUnit: (unit: UnitType) => void;
  formatValue: (val: number) => string;
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  wallThickness: number;
  setWallThickness: (val: number) => void;

  // File I/O
  saveProject: () => void;
  openProject: (file: File) => void;
  exportImage: () => void;

  // UI Toggles
  isLayerPanelOpen: boolean;
  setLayerPanelOpen: (open: boolean) => void;

  // Measurement
  setMeasurement: (val: string) => void;
  subscribeMeasurement: (cb: (val: string) => void) => () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const DEFAULT_LAYERS: ILayer[] = [
    { id: 'layer-structure', name: '結構 (柱/樑/牆)', visible: true, locked: false },
    { id: 'layer-partition', name: '輕隔間', visible: true, locked: false },
    { id: 'layer-furniture', name: '家具/設備', visible: true, locked: false },
    { id: 'layer-annotation', name: '標註/文字', visible: true, locked: false },
];

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // History State
  const [history, setHistory] = useState<{shapes: IShape[], layers: ILayer[]}[]>([{ shapes: [], layers: DEFAULT_LAYERS }]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const [projectName, setProjectName] = useState('未命名專案');
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [layers, setLayers] = useState<ILayer[]>(DEFAULT_LAYERS);
  const [activeLayerId, setActiveLayerId] = useState<string>('layer-structure');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [transformMode, setTransformMode] = useState<TransformMode>('translate');
  const [unit, setUnit] = useState<UnitType>('cm');
  const [wallThickness, setWallThickness] = useState<number>(0.01);
  const [isLayerPanelOpen, setLayerPanelOpen] = useState(false);

  // Measurement Listeners
  const measurementListeners = useRef<Set<(val: string) => void>>(new Set());

  const setMeasurement = useCallback((val: string) => {
    measurementListeners.current.forEach(cb => cb(val));
  }, []);

  const subscribeMeasurement = useCallback((cb: (val: string) => void) => {
    measurementListeners.current.add(cb);
    return () => {
        measurementListeners.current.delete(cb);
    };
  }, []);

  // Internal helper to commit changes to history
  const _commitState = (newShapes: IShape[], newLayers: ILayer[]) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push({ shapes: newShapes, layers: newLayers });
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
    setShapes(newShapes);
    setLayers(newLayers);
  };

  const undo = useCallback(() => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex].shapes);
      setLayers(history[newIndex].layers);
      setSelectedIds([]);
    }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex].shapes);
      setLayers(history[newIndex].layers);
      setSelectedIds([]);
    }
  }, [history, historyIndex]);

  // --- Layer Logic ---
  const addLayer = useCallback((name: string) => {
      const newLayer: ILayer = {
          id: `layer-${Date.now()}`,
          name: name || '新圖層',
          visible: true,
          locked: false
      };
      const newLayers = [...layers, newLayer];
      _commitState(shapes, newLayers);
      setActiveLayerId(newLayer.id);
  }, [layers, shapes, historyIndex, history]);

  const removeLayer = useCallback((id: string) => {
      if (layers.length <= 1) return; // Prevent deleting last layer
      const newLayers = layers.filter(l => l.id !== id);
      // Move shapes from deleted layer to the first available layer
      const fallbackLayerId = newLayers[0].id;
      const newShapes = shapes.map(s => s.layerId === id ? { ...s, layerId: fallbackLayerId } : s);

      if (activeLayerId === id) setActiveLayerId(fallbackLayerId);

      _commitState(newShapes, newLayers);
  }, [layers, shapes, activeLayerId, historyIndex, history]);

  const toggleLayerVisibility = useCallback((id: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, visible: !l.visible } : l);
      // We don't commit visibility to history to avoid spamming undo stack with UI toggles, usually
      // But for consistency let's commit it or just set state. 
      // Let's just set state for visibility to keep it fast.
      setLayers(newLayers); 
      // Optionally update history tip if we want undo to track visibility
      // _commitState(shapes, newLayers);
  }, [layers]);

  const updateLayerName = useCallback((id: string, name: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, name } : l);
      _commitState(shapes, newLayers);
  }, [layers, shapes, historyIndex, history]);


  // --- Shape Logic ---

  const addShape = useCallback((shape: IShape) => {
    // Ensure shape has a layer. If not provided, use active.
    const finalShape = { ...shape, layerId: shape.layerId || activeLayerId };
    const newShapes = [...shapes, finalShape];
    _commitState(newShapes, layers);
    setSelectedIds([shape.id]);
  }, [shapes, layers, activeLayerId, historyIndex, history]);

  const updateShape = useCallback((id: string, updates: Partial<IShape>) => {
    const newShapes = shapes.map(s => s.id === id ? { ...s, ...updates } : s);
    _commitState(newShapes, layers);
  }, [shapes, layers, historyIndex, history]);

  const updateShapes = useCallback((updates: { id: string; changes: Partial<IShape> }[]) => {
    const newShapes = shapes.map(s => {
      const update = updates.find(u => u.id === s.id);
      return update ? { ...s, ...update.changes } : s;
    });
    _commitState(newShapes, layers);
  }, [shapes, layers, historyIndex, history]);

  const removeShape = useCallback((id: string) => {
    const newShapes = shapes.filter(s => s.id !== id);
    _commitState(newShapes, layers);
    if (selectedIds.includes(id)) setSelectedIds(prev => prev.filter(pid => pid !== id));
  }, [shapes, layers, selectedIds, historyIndex, history]);

  const removeSelected = useCallback(() => {
    if (selectedIds.length === 0) return;
    const newShapes = shapes.filter(s => !selectedIds.includes(s.id));
    _commitState(newShapes, layers);
    setSelectedIds([]);
  }, [shapes, layers, selectedIds, historyIndex, history]);

  const replaceShapes = useCallback((idsToRemove: string[], newShapes: IShape[]) => {
    const filteredCurrent = shapes.filter(s => !idsToRemove.includes(s.id));
    // Assign active layer to new shapes if they don't have one
    const labeledNewShapes = newShapes.map(s => ({ ...s, layerId: s.layerId || activeLayerId }));
    const combined = [...filteredCurrent, ...labeledNewShapes];
    _commitState(combined, layers);
    if (newShapes.length === 1) setSelectedIds([newShapes[0].id]);
    else setSelectedIds([]);
  }, [shapes, layers, activeLayerId, historyIndex, history]);

  const copySelected = useCallback(() => {
    if (selectedIds.length === 0) return;

    const groupMapping: Record<string, string> = {};

    const newShapesToAdd = shapes
      .filter(s => selectedIds.includes(s.id))
      .map(s => {
         let newGroupId = undefined;
         if (s.groupId) {
             if (!groupMapping[s.groupId]) {
                 groupMapping[s.groupId] = `group-${Date.now()}-${Math.random()}`;
             }
             newGroupId = groupMapping[s.groupId];
         }

         return {
            ...s,
            id: `copy-${Date.now()}-${Math.random()}`,
            groupId: newGroupId,
            name: `${s.name}`,
            position: [s.position[0] + 1, s.position[1], s.position[2] + 1] as [number, number, number]
         };
      });

    const newShapes = [...shapes, ...newShapesToAdd];
    _commitState(newShapes, layers);
    setSelectedIds(newShapesToAdd.map(s => s.id));
  }, [shapes, layers, selectedIds, historyIndex, history]);

  const groupSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      const newGroupId = `group-${Date.now()}`;

      const updates = selectedIds.map(id => ({
          id,
          changes: { groupId: newGroupId }
      }));
      updateShapes(updates);
  }, [selectedIds, updateShapes]);

  const ungroupSelected = useCallback(() => {
      if (selectedIds.length === 0) return;
      const updates = selectedIds.map(id => ({
          id,
          changes: { groupId: undefined }
      }));
      updateShapes(updates);
  }, [selectedIds, updateShapes]);

  const clearScene = useCallback(() => {
    _commitState([], DEFAULT_LAYERS);
    setSelectedIds([]);
  }, [historyIndex, history]);

  const addAIShapes = useCallback((items: any[]) => {
    const newGeneratedShapes: IShape[] = items.map((item, index) => {
      const w = item.width / 2;
      const d = item.depth / 2;
      const points: IPoint[] = [
        { x: -w, y: 0, z: -d },
        { x: w, y: 0, z: -d },
        { x: w, y: 0, z: d },
        { x: -w, y: 0, z: d },
        { x: -w, y: 0, z: -d },
      ];

      return {
        id: `ai-${Date.now()}-${index}`,
        layerId: 'layer-furniture', // Default AI to furniture
        type: 'solid',
        name: item.name,
        points,
        height: item.height,
        color: item.color || DEFAULT_COLOR,
        position: [item.x, 0, item.z],
        rotation: 0,
        scale: [1, 1, 1]
      };
    });

    const newShapes = [...shapes, ...newGeneratedShapes];
    _commitState(newShapes, layers);
  }, [shapes, layers, historyIndex, history]);

  const formatValue = useCallback((val: number) => {
    if (unit === 'cm') {
      return `${(val * 100).toFixed(0)} cm`;
    }
    return `${val.toFixed(2)} m`;
  }, [unit]);

  const selectShape = useCallback((id: string, multi = false) => {
      const targetShape = shapes.find(s => s.id === id);
      if (!targetShape) return;

      // Ensure we don't select hidden shapes
      const targetLayer = layers.find(l => l.id === targetShape.layerId);
      if (targetLayer && !targetLayer.visible) return;

      let idsToToggle = [id];
      if (targetShape.groupId) {
          idsToToggle = shapes.filter(s => s.groupId === targetShape.groupId).map(s => s.id);
      }

      if (multi) {
          const allSelected = idsToToggle.every(tid => selectedIds.includes(tid));
          if (allSelected) {
              setSelectedIds(prev => prev.filter(pid => !idsToToggle.includes(pid)));
          } else {
              const newSet = new Set([...selectedIds, ...idsToToggle]);
              setSelectedIds(Array.from(newSet));
          }
      } else {
          setSelectedIds(idsToToggle);
      }
  }, [shapes, layers, selectedIds]);

  const deselectAll = useCallback(() => {
      setSelectedIds([]);
  }, []);

  // --- File I/O ---
  const saveProject = useCallback(() => {
      const data = {
          version: '1.0.0',
          projectName,
          shapes,
          layers,
          activeLayerId
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${projectName}.json`;
      a.click();
      URL.revokeObjectURL(url);
  }, [projectName, shapes, layers, activeLayerId]);

  const openProject = useCallback((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (json.shapes && Array.isArray(json.shapes)) {
                  // Migration for old files: add layerId if missing
                  const migratedShapes = json.shapes.map((s: any) => ({
                      ...s,
                      layerId: s.layerId || DEFAULT_LAYERS[0].id
                  }));

                  setProjectName(json.projectName || '匯入的專案');
                  setShapes(migratedShapes);
                  if (json.layers) setLayers(json.layers);
                  if (json.activeLayerId) setActiveLayerId(json.activeLayerId);

                  // Reset history
                  setHistory([{ shapes: migratedShapes, layers: json.layers || DEFAULT_LAYERS }]);
                  setHistoryIndex(0);
                  setSelectedIds([]);
              }
          } catch (err) {
              console.error("Invalid file format", err);
              alert("檔案格式錯誤");
          }
      };
      reader.readAsText(file);
  }, []);

  const exportImage = useCallback(() => {
      const canvas = document.querySelector('canvas');
      if (canvas) {
          const link = document.createElement('a');
          link.download = `${projectName}.png`;
          link.href = canvas.toDataURL('image/png');
          link.click();
      }
  }, [projectName]);

  return (
    <AppContext.Provider value={{
      projectName,
      setProjectName,
      shapes,
      addShape,
      updateShape,
      updateShapes,
      removeShape,
      removeSelected,
      replaceShapes,
      copySelected,
      groupSelected,
      ungroupSelected,
      selectedIds,
      selectShape,
      deselectAll,
      selectedId: selectedIds.length > 0 ? selectedIds[selectedIds.length - 1] : null,
      setSelectedId: (id) => id ? selectShape(id) : deselectAll(),
      tool,
      setTool,
      transformMode,
      setTransformMode,
      clearScene,
      addAIShapes,
      unit,
      setUnit,
      formatValue,
      undo,
      redo,
      canUndo: historyIndex > 0,
      canRedo: historyIndex < history.length - 1,
      wallThickness,
      setWallThickness,
      setMeasurement,
      subscribeMeasurement,

      layers,
      activeLayerId,
      setActiveLayerId,
      addLayer,
      removeLayer,
      toggleLayerVisibility,
      updateLayerName,

      saveProject,
      openProject,
      exportImage,

      isLayerPanelOpen,
      setLayerPanelOpen
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

