const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = currentPoint;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, 0, minZ),
            new THREE.Vector3(maxX, 0, minZ),
            new THREE.Vector3(maxX, 0, maxZ),
            new THREE.Vector3(minX, 0, maxZ),
            new THREE.Vector3(minX, 0, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    // Update measurement when user types even if mouse doesn't move
    useEffect(() => {
        if (typedInput) {
            updateMeasurement(cursorPos, typedInput);
        }
    }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const intersectPoint = e.point; 

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

        // Filter out invisible layers
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });

        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;

        // Filter shapes for snapping to exclude hidden layers
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        const snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        setCursorPos(snap.position);
        setSnapInfo(snap);

        if (!typedInput) {
             updateMeasurement(snap.position);
        }

    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    // Render Guides for drawing
    const guideLines = useMemo(() => {
        if (drawPoints.length === 0) return null;
        const lastPoint = drawPoints[drawPoints.length - 1];

        const isXAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'x';
        const isZAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'z';

        return (
            <group position={[lastPoint.x, 0, lastPoint.z]}>
                {/* X Axis Guide (Red) */}
                <SimpleLine 
                    points={[new THREE.Vector3(-1000, 0, 0), new THREE.Vector3(1000, 0, 0)]} 
                    color="#ef4444" 
                    dashed={!isXAligned}
                    lineWidth={isXAligned ? 3 : 1}
                    opacity={isXAligned ? 0.8 : 0.3} 
                    depthTest={false}
                />
                {/* Z Axis Guide (Green) */}
                <SimpleLine 
                    points={[new THREE.Vector3(0, 0, -1000), new THREE.Vector3(0, 0, 1000)]} 
                    color="#22c55e" 
                    dashed={!isZAligned}
                    lineWidth={isZAligned ? 3 : 1}
                    opacity={isZAligned ? 0.8 : 0.3}
                    depthTest={false}
                />
            </group>
        );
    }, [drawPoints, snapInfo]);

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                visible={false} 
                onPointerMove={onPointerMove}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>

             {/* Drawing Guides */}
             {guideLines}

             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

