const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;

    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 
    else if (type === 'align') color = '#a855f7'; // Purple for alignment

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments>
                        <edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} />
                        <lineBasicMaterial color={color} depthTest={false} />
                    </lineSegments>
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                </mesh>
            )}

            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;

    let displayType = '';
    switch(type) {
        case 'vertex': displayType = '頂點'; break;
        case 'midpoint': displayType = '中點'; break;
        case 'edge': displayType = '邊緣'; break;
        case 'face': displayType = '表面'; break;
        case 'endpoint': displayType = '端點'; break;
        case 'align': displayType = '對齊'; break;
        default: displayType = '';
    }

    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : type === 'align' ? 'bg-purple-500' : 'bg-green-500'}`} />}
                {displayText}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

const useShapeDrag = (
    shape: IShape,
    isSelected: boolean,
    tool: ToolType,
    updateShape: (id: string, updates: Partial<IShape>) => void,
    setDraggingState: (isDragging: boolean) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        start: new THREE.Vector3(),
        offset: new THREE.Vector3(),
        isDragging: false
    });

    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging || !groupRef.current) return;

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const newPos = new THREE.Vector3().addVectors(intersect, dragInfo.current.offset);
             newPos.x = Math.round(newPos.x / SNAP_GRID) * SNAP_GRID;
             newPos.z = Math.round(newPos.z / SNAP_GRID) * SNAP_GRID;
             newPos.y = dragInfo.current.start.y;

             groupRef.current.position.copy(newPos);
        }
    }, [camera, gl]);

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);

        if (groupRef.current) {
            const finalPos = groupRef.current.position;
            if (finalPos.distanceTo(dragInfo.current.start) > 0.001) {
                updateShape(shape.id, { position: [finalPos.x, finalPos.y, finalPos.z] });
            } else {
                 groupRef.current.position.copy(dragInfo.current.start);
            }
        }
    }, [handlePointerMove, updateShape, shape.id, setDraggingState]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.start.set(shape.position[0], shape.position[1], shape.position[2]);
            dragInfo.current.offset.subVectors(groupRef.current.position, intersect);

            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, camera, gl, handlePointerMove, handlePointerUp, setDraggingState]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [handlePointerMove, handlePointerUp]);

    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState }: ShapeRendererProps) => {
    const { unit, tool, updateShape, layers } = useApp();

    // Check Layer Visibility
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const { groupRef, handlePointerDown } = useShapeDrag(shape, isSelected, tool, updateShape, setDraggingState);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 

            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return;
            if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) {
                found = child;
            }
        });
        if (found && found !== targetObj) {
            setTargetObj(found);
        }
    });
    if (!isEnabled || !targetObj) return null;
    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            space={transformMode === 'scale' ? 'local' : 'world'} 
            makeDefault 
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        if (view === 'top') targetPos.set(0, 20, 0);
        else if (view === 'front') targetPos.set(0, 0, 20);
        else if (view === 'right') targetPos.set(20, 0, 0);
        else return;
        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) {
            (controls as any).target.set(0, 0, 0);
            (controls as any).update();
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = currentPoint;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, 0, minZ),
            new THREE.Vector3(maxX, 0, minZ),
            new THREE.Vector3(maxX, 0, maxZ),
            new THREE.Vector3(minX, 0, maxZ),
            new THREE.Vector3(minX, 0, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    // Update measurement when user types even if mouse doesn't move
    useEffect(() => {
        if (typedInput) {
            updateMeasurement(cursorPos, typedInput);
        }
    }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const intersectPoint = e.point; 

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

        // Filter out invisible layers
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });

        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;

        // Filter shapes for snapping to exclude hidden layers
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        const snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        setCursorPos(snap.position);
        setSnapInfo(snap);

        if (!typedInput) {
             updateMeasurement(snap.position);
        }

    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    // Render Guides for drawing
    const guideLines = useMemo(() => {
        if (drawPoints.length === 0) return null;
        const lastPoint = drawPoints[drawPoints.length - 1];

        const isXAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'x';
        const isZAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'z';

        return (
            <group position={[lastPoint.x, 0, lastPoint.z]}>
                {/* X Axis Guide (Red) */}
                <SimpleLine 
                    points={[new THREE.Vector3(-1000, 0, 0), new THREE.Vector3(1000, 0, 0)]} 
                    color="#ef4444" 
                    dashed={!isXAligned}
                    lineWidth={isXAligned ? 3 : 1}
                    opacity={isXAligned ? 0.8 : 0.3} 
                    depthTest={false}
                />
                {/* Z Axis Guide (Green) */}
                <SimpleLine 
                    points={[new THREE.Vector3(0, 0, -1000), new THREE.Vector3(0, 0, 1000)]} 
                    color="#22c55e" 
                    dashed={!isZAligned}
                    lineWidth={isZAligned ? 3 : 1}
                    opacity={isZAligned ? 0.8 : 0.3}
                    depthTest={false}
                />
            </group>
        );
    }, [drawPoints, snapInfo]);

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                visible={false} 
                onPointerMove={onPointerMove}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>

             {/* Drawing Guides */}
             {guideLines}

             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

const EditorScene: React.FC = () => {
    const { shapes, tool, selectShape, updateShape, addShape, selectedIds } = useApp();
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [isDragging, setDraggingState] = useState(false);

    // Push Pull State
    const [pushPullState, setPushPullState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const pushPullHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {
            if (tool !== ToolType.PUSH_PULL) return;
            e.stopPropagation();
            const shape = shapes.find(s => s.id === e.object.userData.id);
            if (shape) {
                setPushPullState(prev => ({
                    ...prev,
                    mode: 'top',
                    hoveredShapeId: shape.id,
                    dragStartPoint: e.point.clone(),
                    originalHeight: shape.height,
                    dragHeight: shape.height
                }));
                setDraggingState(true);
            }
        },
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => {
            if (pushPullState.mode === 'top' && pushPullState.dragStartPoint && pushPullState.hoveredShapeId) {
                e.stopPropagation();
                const diff = e.point.y - pushPullState.dragStartPoint.y;
                let newHeight = pushPullState.originalHeight + diff;
                if (newHeight < 0.01) newHeight = 0.01;

                setPushPullState(prev => ({ ...prev, dragHeight: newHeight }));
            }
        },
        handlePointerUp: () => {
            if (pushPullState.mode === 'top' && pushPullState.hoveredShapeId && pushPullState.dragHeight) {
                updateShape(pushPullState.hoveredShapeId, { height: pushPullState.dragHeight });
                setPushPullState(prev => ({ ...prev, mode: 'none', dragStartPoint: null, dragHeight: undefined }));
                setDraggingState(false);
            }
        }
    }), [tool, shapes, pushPullState, updateShape]);

    const drawingHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {},
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => {},
        handleClick: (e: ThreeEvent<MouseEvent>) => {
             if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) return;
             e.stopPropagation();
             // Logic to add points
             const p = { x: cursorPos.x, y: 0, z: cursorPos.z };

             if (tool === ToolType.DRAW_RECT && drawPoints.length === 1) {
                 // Finish rect
                 const start = drawPoints[0];
                 const width = Math.abs(p.x - start.x);
                 const depth = Math.abs(p.z - start.z);
                 if (width > 0.1 && depth > 0.1) {
                     const centerX = (p.x + start.x) / 2;
                     const centerZ = (p.z + start.z) / 2;
                     const points = [
                        { x: -width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: -depth/2 },
                     ];
                     addShape({
                         id: `shape-${Date.now()}`,
                         type: 'solid',
                         name: 'Room',
                         points,
                         height: 3,
                         color: '#fff',
                         position: [centerX, 0, centerZ],
                         rotation: 0,
                         scale: [1, 1, 1],
                         layerId: 'layer-structure'
                     });
                     setDrawPoints([]);
                 }
             } else {
                 // Add point
                 setDrawPoints(prev => [...prev, p]);
             }
        }
    }), [tool, cursorPos, drawPoints, addShape]);

    // Clear draw points when tool changes
    useEffect(() => {
        setDrawPoints([]);
    }, [tool]);

    // Handle generic click for drawing on plane (InteractionLayer handles this but we need to capture clicks)
    const handlePlaneClick = (e: ThreeEvent<MouseEvent>) => {
        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
            drawingHandlers.handleClick(e);
        }
    };

    return (
        <>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
            <Environment preset="city" />
            <Grid infiniteGrid fadeDistance={50} cellColor="#cbd5e1" sectionColor="#94a3b8" />
            <OrbitControls makeDefault enabled={!isDragging && tool === ToolType.SELECT} />

            <SelectionGizmo />

            {shapes.map(s => (
                <ShapeRenderer 
                    key={s.id} 
                    shape={s} 
                    isSelected={selectedIds.includes(s.id)}
                    onSelect={(e) => {
                         e.stopPropagation();
                         selectShape(s.id, e.ctrlKey);
                    }}
                    pushPullState={pushPullState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setDraggingState}
                />
            ))}

            <InteractionLayer 
                shapes={shapes}
                tool={tool}
                setCursorPos={setCursorPos}
                setSnapInfo={setSnapInfo}
                cursorPos={cursorPos}
                snapInfo={snapInfo}
                drawPoints={drawPoints}
                isDragging={isDragging}
                drawingHeight={0}
                typedInput=""
            />

            {/* Invisible plane to catch drawing clicks */}
             <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.01, 0]} 
                visible={false}
                onClick={handlePlaneClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full relative bg-slate-100">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 50 }}>
                <EditorScene />
            </Canvas>
            <div className="absolute top-4 left-20 z-10">
