            <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
            </GizmoHelper>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2; // Reduced from 0.3 for better precision
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-4; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    snapAxis?: 'x' | 'z'; // Which axis we are aligned to
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const isPointOnSegmentStrict = (p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3, tolerance = 0.05) => {
    if (p.distanceTo(a) < tolerance || p.distanceTo(b) < tolerance) return false;
    const distSq = distToSegmentSquared(p, a, b);
    return distSq < (tolerance * tolerance);
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};


const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let bestSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    // 1. Default to Grid or Face
    if (intersectedObject && shapeData) {
        bestSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    // 2. Vertex / Endpoint Snapping (Highest Priority)
    // Check start point of current drawing first
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        if (dist < threshold * 1.5) {
            return { position: ptVec, type: 'endpoint', distance: dist };
        }
    }

    // Check all shapes vertices
    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     if (Math.abs(ep.y - cursorPos.y) < 0.2) {
                         const dist = ep.distanceTo(cursorPos);
                         if (dist < threshold) {
                             // Snap found!
                             return { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                         }
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold) {
                 return { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     return { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }

    // 3. Midpoint Snapping (Second Priority)
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;

    for (const shape of shapes) {
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);

             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);

                 if (distMid < threshold && distMid < minEdgeDist) {
                     // Prefer midpoint over generic edge
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }

                 // Generic edge check (done later, but calculated here)
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     // Don't overwrite midpoint if it was found
                     if (!bestEdgeSnap || bestEdgeSnap.type !== 'midpoint') {
                        bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                        minEdgeDist = distEdge;
                     }
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }

    // 4. Axis Alignment Snapping (Inference) - NEW
    // Only works if we have an active previous point to align to
    let bestAlignSnap: SnapResult | null = null;
    if (activePoints && activePoints.length > 0) {
        const lastPt = activePoints[activePoints.length - 1];

        // Check X-Axis alignment (Red Axis) -> Z coordinate matches lastPt.z
        const distZ = Math.abs(cursorPos.z - lastPt.z);
        if (distZ < threshold) {
             const snapPos = new THREE.Vector3(cursorPos.x, cursorPos.y, lastPt.z);
             // Make sure we snap to grid on the free axis as well
             snapPos.x = Math.round(snapPos.x / SNAP_GRID) * SNAP_GRID;

             // If we already have a better snap (like midpoint), we might skip, 
             // but usually inference is useful. Let's create it.
             bestAlignSnap = { position: snapPos, type: 'align', distance: distZ, snapAxis: 'x' };
        }

        // Check Z-Axis alignment (Green Axis) -> X coordinate matches lastPt.x
        const distX = Math.abs(cursorPos.x - lastPt.x);
        if (distX < threshold) {
             // If we already found X-align, check which is closer
             if (!bestAlignSnap || distX < bestAlignSnap.distance) {
                 const snapPos = new THREE.Vector3(lastPt.x, cursorPos.y, cursorPos.z);
                 // Snap free axis to grid
                 snapPos.z = Math.round(snapPos.z / SNAP_GRID) * SNAP_GRID;

                 bestAlignSnap = { position: snapPos, type: 'align', distance: distX, snapAxis: 'z' };
             }
        }
    }

    // Decision Logic: Return the best snap found

    // If we have a midpoint, it usually beats alignment unless alignment is super close? 
    // Actually, explicit geometry snaps (midpoint) usually override inference.
    if (bestEdgeSnap && bestEdgeSnap.type === 'midpoint') return bestEdgeSnap;

    // If we have an alignment snap, it beats generic edge snap or grid
    if (bestAlignSnap) return bestAlignSnap;

    // Fallback to edge snap
    if (bestEdgeSnap) return bestEdgeSnap;

    return bestSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;

    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 
    else if (type === 'align') color = '#a855f7'; // Purple for alignment

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments>
                        <edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} />
                        <lineBasicMaterial color={color} depthTest={false} />
                    </lineSegments>
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                </mesh>
            )}

            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;

    let displayType = '';
    switch(type) {
        case 'vertex': displayType = '頂點'; break;
        case 'midpoint': displayType = '中點'; break;
        case 'edge': displayType = '邊緣'; break;
        case 'face': displayType = '表面'; break;
        case 'endpoint': displayType = '端點'; break;
        case 'align': displayType = '對齊'; break;
        default: displayType = '';
    }

    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : type === 'align' ? 'bg-purple-500' : 'bg-green-500'}`} />}
                {displayText}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

const useShapeDrag = (
    shape: IShape,
    isSelected: boolean,
    tool: ToolType,
    updateShape: (id: string, updates: Partial<IShape>) => void,
    setDraggingState: (isDragging: boolean) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        start: new THREE.Vector3(),
        offset: new THREE.Vector3(),
        isDragging: false
    });

    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging || !groupRef.current) return;

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const newPos = new THREE.Vector3().addVectors(intersect, dragInfo.current.offset);
             newPos.x = Math.round(newPos.x / SNAP_GRID) * SNAP_GRID;
             newPos.z = Math.round(newPos.z / SNAP_GRID) * SNAP_GRID;
             newPos.y = dragInfo.current.start.y;

             groupRef.current.position.copy(newPos);
        }
    }, [camera, gl]);

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);

        if (groupRef.current) {
            const finalPos = groupRef.current.position;
            if (finalPos.distanceTo(dragInfo.current.start) > 0.001) {
                updateShape(shape.id, { position: [finalPos.x, finalPos.y, finalPos.z] });
            } else {
                 groupRef.current.position.copy(dragInfo.current.start);
            }
        }
    }, [handlePointerMove, updateShape, shape.id, setDraggingState]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.start.set(shape.position[0], shape.position[1], shape.position[2]);
            dragInfo.current.offset.subVectors(groupRef.current.position, intersect);

            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, camera, gl, handlePointerMove, handlePointerUp, setDraggingState]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [handlePointerMove, handlePointerUp]);

    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState }: ShapeRendererProps) => {
    const { unit, tool, updateShape, layers } = useApp();

    // Check Layer Visibility
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const { groupRef, handlePointerDown } = useShapeDrag(shape, isSelected, tool, updateShape, setDraggingState);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 

            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return;
            if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) {
                found = child;
            }
        });
        if (found && found !== targetObj) {
            setTargetObj(found);
        }
    });
    if (!isEnabled || !targetObj) return null;
    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            space={transformMode === 'scale' ? 'local' : 'world'} 
            makeDefault 
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = currentPoint;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, 0, minZ),
            new THREE.Vector3(maxX, 0, minZ),
            new THREE.Vector3(maxX, 0, maxZ),
            new THREE.Vector3(minX, 0, maxZ),
            new THREE.Vector3(minX, 0, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    // Update measurement when user types even if mouse doesn't move
    useEffect(() => {
        if (typedInput) {
            updateMeasurement(cursorPos, typedInput);
        }
    }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const intersectPoint = e.point; 

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

        // Filter out invisible layers
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });

        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;

        // Filter shapes for snapping to exclude hidden layers
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        const snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        setCursorPos(snap.position);
        setSnapInfo(snap);

        if (!typedInput) {
             updateMeasurement(snap.position);
        }

    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    // Render Guides for drawing
    const guideLines = useMemo(() => {
        if (drawPoints.length === 0) return null;
        const lastPoint = drawPoints[drawPoints.length - 1];

        const isXAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'x';
        const isZAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'z';

        return (
            <group position={[lastPoint.x, 0, lastPoint.z]}>
                {/* X Axis Guide (Red) */}
                <SimpleLine 
                    points={[new THREE.Vector3(-1000, 0, 0), new THREE.Vector3(1000, 0, 0)]} 
                    color="#ef4444" 
                    dashed={!isXAligned}
                    lineWidth={isXAligned ? 3 : 1}
                    opacity={isXAligned ? 0.8 : 0.3} 
                    depthTest={false}
                />
                {/* Z Axis Guide (Green) */}
                <SimpleLine 
                    points={[new THREE.Vector3(0, 0, -1000), new THREE.Vector3(0, 0, 1000)]} 
                    color="#22c55e" 
                    dashed={!isZAligned}
                    lineWidth={isZAligned ? 3 : 1}
                    opacity={isZAligned ? 0.8 : 0.3}
                    depthTest={false}
                />
            </group>
        );
    }, [drawPoints, snapInfo]);

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                visible={false} 
                onPointerMove={onPointerMove}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>

             {/* Drawing Guides */}
             {guideLines}

             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

const EditorScene: React.FC = () => {
    const { shapes, tool, selectShape, updateShape, addShape, selectedIds } = useApp();
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [isDragging, setDraggingState] = useState(false);

    // Push Pull State
    const [pushPullState, setPushPullState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const pushPullHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {
            if (tool !== ToolType.PUSH_PULL) return;
            e.stopPropagation();
            const shape = shapes.find(s => s.id === e.object.userData.id);
            if (shape) {
                setPushPullState(prev => ({
                    ...prev,
                    mode: 'top',
                    hoveredShapeId: shape.id,
                    dragStartPoint: e.point.clone(),
                    originalHeight: shape.height,
                    dragHeight: shape.height
                }));
                setDraggingState(true);
            }
        },
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => {
            if (pushPullState.mode === 'top' && pushPullState.dragStartPoint && pushPullState.hoveredShapeId) {
                e.stopPropagation();
                const diff = e.point.y - pushPullState.dragStartPoint.y;
                let newHeight = pushPullState.originalHeight + diff;
                if (newHeight < 0.01) newHeight = 0.01;

                setPushPullState(prev => ({ ...prev, dragHeight: newHeight }));
            }
        },
        handlePointerUp: () => {
            if (pushPullState.mode === 'top' && pushPullState.hoveredShapeId && pushPullState.dragHeight) {
                updateShape(pushPullState.hoveredShapeId, { height: pushPullState.dragHeight });
                setPushPullState(prev => ({ ...prev, mode: 'none', dragStartPoint: null, dragHeight: undefined }));
                setDraggingState(false);
            }
        }
    }), [tool, shapes, pushPullState, updateShape]);

    const drawingHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {},
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => {},
        handleClick: (e: ThreeEvent<MouseEvent>) => {
             if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) return;
             e.stopPropagation();
             // Logic to add points
             const p = { x: cursorPos.x, y: 0, z: cursorPos.z };

             if (tool === ToolType.DRAW_RECT && drawPoints.length === 1) {
                 // Finish rect
                 const start = drawPoints[0];
                 const width = Math.abs(p.x - start.x);
                 const depth = Math.abs(p.z - start.z);
                 if (width > 0.1 && depth > 0.1) {
                     const centerX = (p.x + start.x) / 2;
                     const centerZ = (p.z + start.z) / 2;
                     const points = [
                        { x: -width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: -depth/2 },
                     ];
                     addShape({
                         id: `shape-${Date.now()}`,
                         type: 'solid',
                         name: 'Room',
                         points,
                         height: 3,
                         color: '#fff',
                         position: [centerX, 0, centerZ],
                         rotation: 0,
                         scale: [1, 1, 1],
                         layerId: 'layer-structure'
                     });
                     setDrawPoints([]);
                 }
             } else {
                 // Add point
                 setDrawPoints(prev => [...prev, p]);
             }
        }
    }), [tool, cursorPos, drawPoints, addShape]);

    // Clear draw points when tool changes
    useEffect(() => {
        setDrawPoints([]);
    }, [tool]);

    // Handle generic click for drawing on plane (InteractionLayer handles this but we need to capture clicks)
    const handlePlaneClick = (e: ThreeEvent<MouseEvent>) => {
        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
            drawingHandlers.handleClick(e);
        }
    };

    return (
        <>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
            <Environment preset="city" />
            <Grid infiniteGrid fadeDistance={50} cellColor="#cbd5e1" sectionColor="#94a3b8" />
            <OrbitControls makeDefault enabled={!isDragging && tool === ToolType.SELECT} />

            <SelectionGizmo />

            {shapes.map(s => (
                <ShapeRenderer 
                    key={s.id} 
                    shape={s} 
                    isSelected={selectedIds.includes(s.id)}
                    onSelect={(e) => {
                         e.stopPropagation();
                         selectShape(s.id, e.ctrlKey);
                    }}
                    pushPullState={pushPullState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setDraggingState}
                />
            ))}

            <InteractionLayer 
                shapes={shapes}
                tool={tool}
                setCursorPos={setCursorPos}
                setSnapInfo={setSnapInfo}
                cursorPos={cursorPos}
                snapInfo={snapInfo}
                drawPoints={drawPoints}
                isDragging={isDragging}
                drawingHeight={0}
                typedInput=""
            />

            {/* Invisible plane to catch drawing clicks */}
             <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.01, 0]} 
                visible={false}
                onClick={handlePlaneClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full relative bg-slate-100">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 50 }}>
                <EditorScene />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
                </GizmoHelper>
            </Canvas>
            <div className="absolute top-4 left-20 z-10">
                <AIAssistant />
            </div>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2; // Reduced from 0.3 for better precision
const ALIGN_THRESHOLD = 0.25; // Meters (Object alignment radius)
const EPSILON = 1e-4; // Floating point tolerance

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string; // ID of the object we snapped to
    snapEdge?: [THREE.Vector3, THREE.Vector3]; // The start/end of the edge we snapped to (for highlighting)
    snapAxis?: 'x' | 'z'; // Which axis we are aligned to
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number; // Current dynamic height during drag
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

const isPointOnSegmentStrict = (p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3, tolerance = 0.05) => {
    if (p.distanceTo(a) < tolerance || p.distanceTo(b) < tolerance) return false;
    const distSq = distToSegmentSquared(p, a, b);
    return distSq < (tolerance * tolerance);
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};


const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let bestSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    // 1. Default to Grid or Face
    if (intersectedObject && shapeData) {
        bestSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    // 2. Vertex / Endpoint Snapping (Highest Priority)
    // Check start point of current drawing first
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        if (dist < threshold * 1.5) {
            return { position: ptVec, type: 'endpoint', distance: dist };
        }
    }

    // Check all shapes vertices
    for (const shape of shapes) {
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     if (Math.abs(ep.y - cursorPos.y) < 0.2) {
                         const dist = ep.distanceTo(cursorPos);
                         if (dist < threshold) {
                             // Snap found!
                             return { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                         }
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);

            if (dist < threshold) {
                 return { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = worldPtTop.distanceTo(cursorPos);
                if (dist < threshold) {
                     return { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                }
            }
        }
    }

    // 3. Midpoint Snapping (Second Priority)
    let bestEdgeSnap: SnapResult | null = null;
    let minEdgeDist = threshold;

    for (const shape of shapes) {
        const pts = shape.points;
        const len = pts.length;
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < len; i++) {
             const p1 = transformPoint(pts[i], shape);
             const p2 = transformPoint(pts[(i + 1) % len], shape);

             const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                 const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                 const distMid = mid.distanceTo(cursorPos);

                 if (distMid < threshold && distMid < minEdgeDist) {
                     // Prefer midpoint over generic edge
                     bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                     minEdgeDist = distMid;
                     return;
                 }

                 // Generic edge check (done later, but calculated here)
                 const projected = closestPointOnSegment(cursorPos, v1, v2);
                 const distEdge = projected.distanceTo(cursorPos);
                 if (distEdge < threshold && distEdge < minEdgeDist) {
                     // Don't overwrite midpoint if it was found
                     if (!bestEdgeSnap || bestEdgeSnap.type !== 'midpoint') {
                        bestEdgeSnap = { position: projected, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                        minEdgeDist = distEdge;
                     }
                 }
             };
             checkSegment(p1, p2);
             if (hasHeight) {
                 const p1Top = p1.clone().setY(p1.y + currentH);
                 const p2Top = p2.clone().setY(p2.y + currentH);
                 checkSegment(p1Top, p2Top);
                 checkSegment(p1, p1Top);
             }
        }
    }

    // 4. Axis Alignment Snapping (Inference) - NEW
    // Only works if we have an active previous point to align to
    let bestAlignSnap: SnapResult | null = null;
    if (activePoints && activePoints.length > 0) {
        const lastPt = activePoints[activePoints.length - 1];

        // Check X-Axis alignment (Red Axis) -> Z coordinate matches lastPt.z
        const distZ = Math.abs(cursorPos.z - lastPt.z);
        if (distZ < threshold) {
             const snapPos = new THREE.Vector3(cursorPos.x, cursorPos.y, lastPt.z);
             // Make sure we snap to grid on the free axis as well
             snapPos.x = Math.round(snapPos.x / SNAP_GRID) * SNAP_GRID;

             // If we already have a better snap (like midpoint), we might skip, 
             // but usually inference is useful. Let's create it.
             bestAlignSnap = { position: snapPos, type: 'align', distance: distZ, snapAxis: 'x' };
        }

        // Check Z-Axis alignment (Green Axis) -> X coordinate matches lastPt.x
        const distX = Math.abs(cursorPos.x - lastPt.x);
        if (distX < threshold) {
             // If we already found X-align, check which is closer
             if (!bestAlignSnap || distX < bestAlignSnap.distance) {
                 const snapPos = new THREE.Vector3(lastPt.x, cursorPos.y, cursorPos.z);
                 // Snap free axis to grid
                 snapPos.z = Math.round(snapPos.z / SNAP_GRID) * SNAP_GRID;

                 bestAlignSnap = { position: snapPos, type: 'align', distance: distX, snapAxis: 'z' };
             }
        }
    }

    // Decision Logic: Return the best snap found

    // If we have a midpoint, it usually beats alignment unless alignment is super close? 
    // Actually, explicit geometry snaps (midpoint) usually override inference.
    if (bestEdgeSnap && bestEdgeSnap.type === 'midpoint') return bestEdgeSnap;

    // If we have an alignment snap, it beats generic edge snap or grid
    if (bestAlignSnap) return bestAlignSnap;

    // Fallback to edge snap
    if (bestEdgeSnap) return bestEdgeSnap;

    return bestSnap;
};

// ... Components ...

const SimpleLine: React.FC<{ points: (THREE.Vector3 | [number, number, number])[], color: string, dashed?: boolean, opacity?: number, transparent?: boolean, lineWidth?: number, depthTest?: boolean }> = ({ points, color, dashed, opacity, transparent, lineWidth, depthTest = true }) => {
    const ref = useRef<THREE.Line>(null);
    const geometry = useMemo(() => {
        const pts = points.map(p => (p instanceof THREE.Vector3 ? p : new THREE.Vector3(...p)));
        return new THREE.BufferGeometry().setFromPoints(pts);
    }, [points]);

    useLayoutEffect(() => {
        if (dashed && ref.current) {
            ref.current.computeLineDistances();
        }
    }, [geometry, dashed]);

    return (
        <line ref={ref} geometry={geometry}>
            {dashed ? (
                <lineDashedMaterial color={color} dashSize={0.2} gapSize={0.1} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            ) : (
                <lineBasicMaterial color={color} transparent={transparent} opacity={opacity} depthTest={depthTest} toneMapped={false} />
            )}
        </line>
    );
};

const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid') return null;

    let color = 'orange';
    if (type === 'midpoint') color = 'cyan';
    else if (type === 'vertex' || type === 'endpoint') color = '#ec4899'; 
    else if (type === 'face') color = '#3b82f6'; 
    else if (type === 'align') color = '#a855f7'; // Purple for alignment

    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments>
                        <edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} />
                        <lineBasicMaterial color={color} depthTest={false} />
                    </lineSegments>
                 </mesh>
            ) : (
                <mesh>
                    <sphereGeometry args={[type === 'vertex' || type === 'endpoint' ? 0.12 : 0.05]} />
                    <meshBasicMaterial color={color} depthTest={false} />
                </mesh>
            )}

            {type === 'edge' && snapEdge && (
                <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="orange" lineWidth={3} depthTest={false} />
            )}
            {type === 'midpoint' && snapEdge && (
                 <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="cyan" lineWidth={3} depthTest={false} />
            )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid') return null;

    let displayType = '';
    switch(type) {
        case 'vertex': displayType = '頂點'; break;
        case 'midpoint': displayType = '中點'; break;
        case 'edge': displayType = '邊緣'; break;
        case 'face': displayType = '表面'; break;
        case 'endpoint': displayType = '端點'; break;
        case 'align': displayType = '對齊'; break;
        default: displayType = '';
    }

    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none' }}>
            <div className="bg-slate-900/80 text-white text-xs px-2 py-1 rounded backdrop-blur-sm border border-slate-600 whitespace-nowrap flex items-center gap-1">
                {type && <span className={`w-2 h-2 rounded-full ${type === 'grid' ? 'bg-slate-500' : type === 'face' ? 'bg-blue-500' : type === 'align' ? 'bg-purple-500' : 'bg-green-500'}`} />}
                {displayText}
            </div>
        </Html>
    );
};

const ShapeOutline: React.FC<{ shape: IShape; color: string; opacity: number }> = ({ shape, color, opacity }) => {
    const geometry = useMemo(() => {
        const shape2D = createThreeShape(shape.points);
        const geom = new THREE.ExtrudeGeometry(shape2D, { depth: shape.height, bevelEnabled: false });
        return new THREE.EdgesGeometry(geom);
    }, [shape.points, shape.height]);

    return (
        <lineSegments geometry={geometry} rotation={[-Math.PI / 2, 0, 0]}>
            <lineBasicMaterial color={color} transparent opacity={opacity} />
        </lineSegments>
    );
};

const useShapeDrag = (
    shape: IShape,
    isSelected: boolean,
    tool: ToolType,
    updateShape: (id: string, updates: Partial<IShape>) => void,
    setDraggingState: (isDragging: boolean) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        start: new THREE.Vector3(),
        offset: new THREE.Vector3(),
        isDragging: false
    });

    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging || !groupRef.current) return;

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const newPos = new THREE.Vector3().addVectors(intersect, dragInfo.current.offset);
             newPos.x = Math.round(newPos.x / SNAP_GRID) * SNAP_GRID;
             newPos.z = Math.round(newPos.z / SNAP_GRID) * SNAP_GRID;
             newPos.y = dragInfo.current.start.y;

             groupRef.current.position.copy(newPos);
        }
    }, [camera, gl]);

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);

        if (groupRef.current) {
            const finalPos = groupRef.current.position;
            if (finalPos.distanceTo(dragInfo.current.start) > 0.001) {
                updateShape(shape.id, { position: [finalPos.x, finalPos.y, finalPos.z] });
            } else {
                 groupRef.current.position.copy(dragInfo.current.start);
            }
        }
    }, [handlePointerMove, updateShape, shape.id, setDraggingState]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.start.set(shape.position[0], shape.position[1], shape.position[2]);
            dragInfo.current.offset.subVectors(groupRef.current.position, intersect);

            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, camera, gl, handlePointerMove, handlePointerUp, setDraggingState]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [handlePointerMove, handlePointerUp]);

    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState }: ShapeRendererProps) => {
    const { unit, tool, updateShape, layers } = useApp();

    const { groupRef, handlePointerDown } = useShapeDrag(shape, isSelected, tool, updateShape, setDraggingState);

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    // Check Layer Visibility (Moved after hooks)
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 

            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
            </mesh>
            <ShapeOutline shape={shape} color="#333" opacity={isPushPullMode ? 0.2 : 0.5} />
        </group>
    );
});

const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return;
            if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) {
                found = child;
            }
        });
        if (found && found !== targetObj) {
            setTargetObj(found);
        }
    });
    if (!isEnabled || !targetObj) return null;
    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            space={transformMode === 'scale' ? 'local' : 'world'} 
            makeDefault 
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const DrawingPreview: React.FC<{ tool: ToolType; points: IPoint[]; cursorPos: THREE.Vector3 }> = ({ tool, points, cursorPos }) => {
    const currentPoint = cursorPos;
    if (points.length === 0) return null;
    const startPoint = points[0];

    const startVec = new THREE.Vector3(startPoint.x, startPoint.y, startPoint.z);

    if (tool === ToolType.DRAW_LINE) {
        const linePoints = points.map(p => new THREE.Vector3(p.x, p.y, p.z));
        linePoints.push(currentPoint);
        return <SimpleLine points={linePoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_RECT) {
        const p1 = startVec;
        const p2 = currentPoint;

        const minX = Math.min(p1.x, p2.x);
        const maxX = Math.max(p1.x, p2.x);
        const minZ = Math.min(p1.z, p2.z);
        const maxZ = Math.max(p1.z, p2.z);

        const rectPoints = [
            new THREE.Vector3(minX, 0, minZ),
            new THREE.Vector3(maxX, 0, minZ),
            new THREE.Vector3(maxX, 0, maxZ),
            new THREE.Vector3(minX, 0, maxZ),
            new THREE.Vector3(minX, 0, minZ),
        ];

        return <SimpleLine points={rectPoints} color="black" dashed />;
    }

    if (tool === ToolType.DRAW_CIRCLE) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const circlePoints = createCirclePoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
        return (
            <>
                <SimpleLine points={circlePoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    if (tool === ToolType.DRAW_ARC) {
        const radius = startVec.distanceTo(currentPoint);
        if (radius < 0.01) return null;
        const arcPoints = createArcPoints(radius).map(p => new THREE.Vector3(p.x + startPoint.x, 0, p.z + startPoint.z));
         return (
            <>
                <SimpleLine points={arcPoints} color="black" dashed />
                <SimpleLine points={[startVec, currentPoint]} color="gray" dashed opacity={0.5} />
            </>
        );
    }

    return null;
};

const InteractionLayer: React.FC<{
    shapes: IShape[];
    tool: ToolType;
    setCursorPos: (v: THREE.Vector3) => void;
    setSnapInfo: (s: SnapResult | null) => void;
    cursorPos: THREE.Vector3;
    snapInfo: SnapResult | null;
    drawPoints: IPoint[];
    isDragging: boolean;
    drawingHeight: number;
    typedInput: string;
}> = ({ shapes, tool, setCursorPos, setSnapInfo, cursorPos, snapInfo, drawPoints, isDragging, drawingHeight, typedInput }) => {
    const { camera, scene } = useThree();
    const { setMeasurement, formatValue, layers } = useApp();

    const updateMeasurement = useCallback((pos: THREE.Vector3, input?: string) => {
        let text = '';
        if (drawPoints.length > 0) {
            const start = drawPoints[drawPoints.length - 1]; // Last point
            const current = pos;

            // Calculate 3D distance
            const dist = Math.sqrt(
                (current.x - start.x)**2 + 
                (current.y - start.y)**2 + 
                (current.z - start.z)**2
            );

            if (tool === ToolType.DRAW_LINE) {
                text = `長度: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_RECT) {
                if (input) {
                    text = `寬度, 深度: ${input}`;
                } else {
                    const w = Math.abs(current.x - start.x);
                    const d = Math.abs(current.z - start.z);
                    text = `寬度: ${formatValue(w)}, 深度: ${formatValue(d)}`;
                }
            } else if (tool === ToolType.DRAW_CIRCLE) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            } else if (tool === ToolType.DRAW_ARC) {
                 text = `半徑: ${input ? input : formatValue(dist)}`;
            }
        } else {
             // Basic coordinate display when hovering
             if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
                 text = `起點: X ${formatValue(pos.x)}, Z ${formatValue(pos.z)}`;
             }
        }

        if (input !== undefined) {
             text += '|'; // Add cursor block
        }
        setMeasurement(text);
    }, [drawPoints, tool, formatValue, setMeasurement]);

    // Update measurement when user types even if mouse doesn't move
    useEffect(() => {
        if (typedInput) {
            updateMeasurement(cursorPos, typedInput);
        }
    }, [typedInput, cursorPos, updateMeasurement]);

    const onPointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;

        const intersectPoint = e.point; 

        const shapeIntersections = e.intersections.filter(i => (i.object.userData?.isShape || i.object.parent?.userData?.isShape) && i.object !== e.object);

        // Filter out invisible layers
        const visibleIntersections = shapeIntersections.filter(i => {
            const obj = i.object;
            const shapeId = obj.userData?.id || obj.parent?.userData?.id;
            const shape = shapes.find(s => s.id === shapeId);
            if (!shape) return false;
            const layer = layers.find(l => l.id === shape.layerId);
            return layer ? layer.visible : true;
        });

        const topShapeIntersect = visibleIntersections.length > 0 ? visibleIntersections[0] : undefined;

        // Filter shapes for snapping to exclude hidden layers
        const visibleShapes = shapes.filter(s => {
             const layer = layers.find(l => l.id === s.layerId);
             return layer ? layer.visible : true;
        });

        const snap = getGeometrySnap(intersectPoint, visibleShapes, drawPoints, SNAP_THRESHOLD, topShapeIntersect);

        setCursorPos(snap.position);
        setSnapInfo(snap);

        if (!typedInput) {
             updateMeasurement(snap.position);
        }

    }, [tool, shapes, layers, drawPoints, setCursorPos, setSnapInfo, updateMeasurement, typedInput]);

    // Render Guides for drawing (moved before early return)
    const guideLines = useMemo(() => {
        if (drawPoints.length === 0) return null;
        const lastPoint = drawPoints[drawPoints.length - 1];

        const isXAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'x';
        const isZAligned = snapInfo?.type === 'align' && snapInfo.snapAxis === 'z';

        return (
            <group position={[lastPoint.x, 0, lastPoint.z]}>
                {/* X Axis Guide (Red) */}
                <SimpleLine 
                    points={[new THREE.Vector3(-1000, 0, 0), new THREE.Vector3(1000, 0, 0)]} 
                    color="#ef4444" 
                    dashed={!isXAligned}
                    lineWidth={isXAligned ? 3 : 1}
                    opacity={isXAligned ? 0.8 : 0.3} 
                    depthTest={false}
                />
                {/* Z Axis Guide (Green) */}
                <SimpleLine 
                    points={[new THREE.Vector3(0, 0, -1000), new THREE.Vector3(0, 0, 1000)]} 
                    color="#22c55e" 
                    dashed={!isZAligned}
                    lineWidth={isZAligned ? 3 : 1}
                    opacity={isZAligned ? 0.8 : 0.3}
                    depthTest={false}
                />
            </group>
        );
    }, [drawPoints, snapInfo]);

    if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return null;

    return (
        <group>
            <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.005, 0]} 
                visible={false} 
                onPointerMove={onPointerMove}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>

             {/* Drawing Guides */}
             {guideLines}

             {snapInfo && (
                <>
                    <SnapIndicator position={snapInfo.position} type={snapInfo.type} snapEdge={snapInfo.snapEdge} />
                    <CursorTooltip text={snapInfo.type === 'none' ? '' : snapInfo.type} position={snapInfo.position} type={snapInfo.type} />
                </>
             )}

             {drawPoints.length > 0 && (
                <DrawingPreview tool={tool} points={drawPoints} cursorPos={cursorPos} />
             )}
        </group>
    );
};

const EditorScene: React.FC = () => {
    const { shapes, tool, selectShape, updateShape, addShape, selectedIds } = useApp();
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [isDragging, setDraggingState] = useState(false);

    // Push Pull State
    const [pushPullState, setPushPullState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });

    const pushPullHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {
            if (tool !== ToolType.PUSH_PULL) return;
            e.stopPropagation();
            const shape = shapes.find(s => s.id === e.object.userData.id);
            if (shape) {
                setPushPullState(prev => ({
                    ...prev,
                    mode: 'top',
                    hoveredShapeId: shape.id,
                    dragStartPoint: e.point.clone(),
                    originalHeight: shape.height,
                    dragHeight: shape.height
                }));
                setDraggingState(true);
            }
        },
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => {
            if (pushPullState.mode === 'top' && pushPullState.dragStartPoint && pushPullState.hoveredShapeId) {
                e.stopPropagation();
                const diff = e.point.y - pushPullState.dragStartPoint.y;
                let newHeight = pushPullState.originalHeight + diff;
                if (newHeight < 0.01) newHeight = 0.01;

                setPushPullState(prev => ({ ...prev, dragHeight: newHeight }));
            }
        },
        handlePointerUp: () => {
            if (pushPullState.mode === 'top' && pushPullState.hoveredShapeId && pushPullState.dragHeight) {
                updateShape(pushPullState.hoveredShapeId, { height: pushPullState.dragHeight });
                setPushPullState(prev => ({ ...prev, mode: 'none', dragStartPoint: null, dragHeight: undefined }));
                setDraggingState(false);
            }
        }
    }), [tool, shapes, pushPullState, updateShape]);

    const drawingHandlers = useMemo(() => ({
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => {},
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => {},
        handleClick: (e: ThreeEvent<MouseEvent>) => {
             if (![ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) return;
             e.stopPropagation();
             // Logic to add points
             const p = { x: cursorPos.x, y: 0, z: cursorPos.z };

             if (tool === ToolType.DRAW_RECT && drawPoints.length === 1) {
                 // Finish rect
                 const start = drawPoints[0];
                 const width = Math.abs(p.x - start.x);
                 const depth = Math.abs(p.z - start.z);
                 if (width > 0.1 && depth > 0.1) {
                     const centerX = (p.x + start.x) / 2;
                     const centerZ = (p.z + start.z) / 2;
                     const points = [
                        { x: -width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: -depth/2 },
                        { x: width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: depth/2 },
                        { x: -width/2, y: 0, z: -depth/2 },
                     ];
                     addShape({
                         id: `shape-${Date.now()}`,
                         type: 'solid',
                         name: 'Room',
                         points,
                         height: 3,
                         color: '#fff',
                         position: [centerX, 0, centerZ],
                         rotation: 0,
                         scale: [1, 1, 1],
                         layerId: 'layer-structure'
                     });
                     setDrawPoints([]);
                 }
             } else {
                 // Add point
                 setDrawPoints(prev => [...prev, p]);
             }
        }
    }), [tool, cursorPos, drawPoints, addShape]);

    // Clear draw points when tool changes
    useEffect(() => {
        setDrawPoints([]);
    }, [tool]);

    // Handle generic click for drawing on plane (InteractionLayer handles this but we need to capture clicks)
    const handlePlaneClick = (e: ThreeEvent<MouseEvent>) => {
        if ([ToolType.DRAW_LINE, ToolType.DRAW_RECT, ToolType.DRAW_CIRCLE, ToolType.DRAW_ARC].includes(tool)) {
            drawingHandlers.handleClick(e);
        }
    };

    return (
        <>
            <ambientLight intensity={0.5} />
            <directionalLight position={[10, 20, 10]} intensity={1} castShadow />
            <Environment preset="city" />
            <Grid infiniteGrid fadeDistance={50} cellColor="#cbd5e1" sectionColor="#94a3b8" />
            <OrbitControls makeDefault enabled={!isDragging && tool === ToolType.SELECT} />

            <SelectionGizmo />

            {shapes.map(s => (
                <ShapeRenderer 
                    key={s.id} 
                    shape={s} 
                    isSelected={selectedIds.includes(s.id)}
                    onSelect={(e) => {
                         e.stopPropagation();
                         selectShape(s.id, e.ctrlKey);
                    }}
                    pushPullState={pushPullState}
                    pushPullHandlers={pushPullHandlers}
                    drawingHandlers={drawingHandlers}
                    setDraggingState={setDraggingState}
                />
            ))}

            <InteractionLayer 
                shapes={shapes}
                tool={tool}
                setCursorPos={setCursorPos}
                setSnapInfo={setSnapInfo}
                cursorPos={cursorPos}
                snapInfo={snapInfo}
                drawPoints={drawPoints}
                isDragging={isDragging}
                drawingHeight={0}
                typedInput=""
            />

            {/* Invisible plane to catch drawing clicks */}
             <mesh 
                rotation={[-Math.PI / 2, 0, 0]} 
                position={[0, 0.01, 0]} 
                visible={false}
                onClick={handlePlaneClick}
            >
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial />
            </mesh>
        </>
    );
};

const Viewport: React.FC = () => {
    return (
        <div className="w-full h-full relative bg-slate-100">
            <Canvas shadows camera={{ position: [5, 8, 8], fov: 50 }}>
                <EditorScene />
                <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
                    <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="black" />
                </GizmoHelper>
            </Canvas>
            <div className="absolute top-4 left-20 z-10">
                <AIAssistant />
            </div>
        </div>
    );
};

export default Viewport;

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, Environment, TransformControls, Html, GizmoHelper, GizmoViewport } from '@react-three/drei';
import * as THREE from 'three';
import { OrbitControls as OrbitControlsImpl } from 'three-stdlib';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, ShapeType } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.2;
const ALIGN_THRESHOLD = 0.25;
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
    snapAxis?: 'x' | 'z';
    guides?: THREE.Vector3[][];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const createArcPoints = (radius: number, segments = 16): IPoint[] => {
  const points: IPoint[] = [];
  points.push({ x: 0, y: 0, z: 0 });
  for (let i = 0; i <= segments; i++) {
    const theta = (i / segments) * (Math.PI / 2); 
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push({ x: 0, y: 0, z: 0 });
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    if (u >= 0 && u <= 1 && v >= 0 && v <= 1) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

// --- Polygon Splitting Logic ---
// Checks if a segment (A-B) splits a polygon into two. Returns the two new polygons or null.
const splitPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    const intersections: { point: IPoint; edgeIndex: number; dist: number }[] = [];

    // 1. Find all intersections between the cut line and the polygon edges
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getLineIntersection(p1, p2, lineStart, lineEnd);
        if (hit) {
            // Check if this hit is unique (avoid floating point dupes)
            const isDuplicate = intersections.some(h => 
                Math.abs(h.point.x - hit.x) < 0.001 && Math.abs(h.point.z - hit.z) < 0.001
            );
            if (!isDuplicate) {
                const distFromStart = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist: distFromStart });
            }
        }
    }

    // We only support simple cuts (entering and exiting), so we need exactly 2 intersections
    if (intersections.length !== 2) return null;

    // Sort intersections by distance along the cut line (start to end)
    intersections.sort((a, b) => a.dist - b.dist);
    const [hit1, hit2] = intersections;

    // 2. Construct Poly A
    // Start from hit1, go along polygon until hit2, then cut back to hit1
    const polyA: IPoint[] = [hit1.point];

    // Add points from the original polygon
    let idx = (hit1.edgeIndex + 1) % polyPoints.length;
    // Special handling: if hit1 is on edge i, the next vertex is i+1.
    // We traverse until we pass hit2's edge.

    // Using a safety loop counter
    let safety = 0;
    while (true && safety < polyPoints.length * 2) {
        // Current segment is from idx-1 to idx (conceptually)
        // If hit2 is on the edge starting at current pointer `idx`? No, hit2 has `edgeIndex`.

        // If the previous vertex index matches hit2's edgeIndex, we add hit2 and stop
        const prevIdx = (idx - 1 + polyPoints.length) % polyPoints.length;
        if (prevIdx === hit2.edgeIndex) {
            polyA.push(hit2.point);
            break;
        }

        polyA.push(polyPoints[idx]);
        idx = (idx + 1) % polyPoints.length;
        safety++;
    }

    // 3. Construct Poly B
    // Start from hit2, go along polygon until hit1, then cut back to hit2
    const polyB: IPoint[] = [hit2.point];
    idx = (hit2.edgeIndex + 1) % polyPoints.length;
    safety = 0;
    while(true && safety < polyPoints.length * 2) {
        const prevIdx = (idx - 1 + polyPoints.length) % polyPoints.length;
        if (prevIdx === hit1.edgeIndex) {
            polyB.push(hit1.point);
            break;
        }
        polyB.push(polyPoints[idx]);
        idx = (idx + 1) % polyPoints.length;
        safety++;
    }

    return [polyA, polyB];
};

const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;
    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });
    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];
    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 
    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;
    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);
    return [p1, p2];
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    let bestSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    // 1. Default to Grid or Face
    if (intersectedObject && shapeData) {
        bestSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        bestSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    // 2. Vertex / Endpoint Snapping (Highest Priority)
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        const dist = ptVec.distanceTo(cursorPos);
        // Larger threshold for closing loops to make it easier
        if (dist < threshold * 1.5) {
            return { position: ptVec, type: 'endpoint', distance: dist };
        }
    }

    for (const shape of shapes) {
        // Vertex snapping
        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = worldPt.distanceTo(cursorPos);
            if (dist < threshold) return { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
        }
    }

    // 3. Axis Alignment (Inference)
    let bestAlignSnap: SnapResult | null = null;
    if (activePoints && activePoints.length > 0) {
        const lastPt = activePoints[activePoints.length - 1];
        const distZ = Math.abs(cursorPos.z - lastPt.z);
        if (distZ < threshold) {
             const snapPos = new THREE.Vector3(cursorPos.x, cursorPos.y, lastPt.z);
             snapPos.x = Math.round(snapPos.x / SNAP_GRID) * SNAP_GRID;
             bestAlignSnap = { position: snapPos, type: 'align', distance: distZ, snapAxis: 'x' };
        }
        const distX = Math.abs(cursorPos.x - lastPt.x);
        if (distX < threshold) {
             if (!bestAlignSnap || distX < bestAlignSnap.distance) {
                 const snapPos = new THREE.Vector3(lastPt.x, cursorPos.y, cursorPos.z);
                 snapPos.z = Math.round(snapPos.z / SNAP_GRID) * SNAP_GRID;
                 bestAlignSnap = { position: snapPos, type: 'align', distance: distX, snapAxis: 'z' };
             }
        }
    }

    if (bestAlignSnap) return bestAlignSnap;
    return bestSnap;
};

